## Webhook Endpoint Implementálása

```javascript
// Webhook endpoint a Stripe eseményekhez
app.post('/webhook', (req, res) => {
  const sig = req.headers['stripe-signature'];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, endpointSecret);
  } catch (err) {
    console.log(`Webhook signature verification failed.`, err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Sikeres fizetés kezelése
  if (event.type === 'payment_intent.succeeded') {
    const paymentIntent = event.data.object;
    console.log('Sikeres fizetés:', paymentIntent.amount);

    // Itt hívd meg a kriptovaluta konverziós függvényt
    convertToCrypto(paymentIntent);
  }

  res.json({received: true});
});
```

